CREATE TABLE healthcare_organization(id VARCHAR(36) PRIMARY KEY, code VARCHAR(20) NOT NULL UNIQUE, legacy_key VARCHAR(100) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, type VARCHAR(30) NOT NULL, parent_id VARCHAR(36) REFERENCES healthcare_organization(id), status VARCHAR(20) NOT NULL, evidence VARCHAR(1000), verified_by VARCHAR(36) REFERENCES app_user(id), verified_at VARCHAR(40), created_by VARCHAR(36) REFERENCES app_user(id), created_at VARCHAR(40) NOT NULL, version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE organization_node(id VARCHAR(36) PRIMARY KEY, organization_id VARCHAR(36) NOT NULL REFERENCES healthcare_organization(id), parent_id VARCHAR(36), kind VARCHAR(30) NOT NULL, name VARCHAR(120) NOT NULL, details TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, version INTEGER NOT NULL DEFAULT 0, UNIQUE(organization_id,id), FOREIGN KEY(organization_id,parent_id) REFERENCES organization_node(organization_id,id));
ALTER TABLE app_user ADD COLUMN organization_id VARCHAR(36) REFERENCES healthcare_organization(id);
CREATE TABLE employment(id VARCHAR(36) PRIMARY KEY, organization_id VARCHAR(36) NOT NULL REFERENCES healthcare_organization(id), user_id VARCHAR(36) NOT NULL UNIQUE REFERENCES app_user(id), work_id VARCHAR(30) NOT NULL UNIQUE, professional_role VARCHAR(40) NOT NULL, node_id VARCHAR(36), start_at VARCHAR(40) NOT NULL, end_at VARCHAR(40), credential_until VARCHAR(40), license_encrypted TEXT, license_jurisdiction VARCHAR(100), specialty VARCHAR(100), credential_status VARCHAR(30) NOT NULL, privileges TEXT NOT NULL, status VARCHAR(20) NOT NULL, created_at VARCHAR(40) NOT NULL, version INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(organization_id,node_id) REFERENCES organization_node(organization_id,id), UNIQUE(organization_id,id));
CREATE TABLE platform_operator(user_id VARCHAR(36) PRIMARY KEY REFERENCES app_user(id));
CREATE TABLE staff_invitation(id VARCHAR(36) PRIMARY KEY, organization_id VARCHAR(36) NOT NULL REFERENCES healthcare_organization(id), token_hash VARCHAR(64) NOT NULL UNIQUE, username VARCHAR(80) NOT NULL, professional_role VARCHAR(40) NOT NULL, department VARCHAR(100) NOT NULL, expires_at VARCHAR(40) NOT NULL, used_at VARCHAR(40), created_by VARCHAR(36) NOT NULL REFERENCES app_user(id), created_at VARCHAR(40) NOT NULL);
CREATE TABLE workforce_shift(id VARCHAR(36) PRIMARY KEY, organization_id VARCHAR(36) NOT NULL REFERENCES healthcare_organization(id), employee_id VARCHAR(36) NOT NULL, node_id VARCHAR(36), kind VARCHAR(30) NOT NULL, starts_at VARCHAR(40) NOT NULL, ends_at VARCHAR(40) NOT NULL, public_booking BOOLEAN NOT NULL DEFAULT FALSE, specialty VARCHAR(100), replaces_id VARCHAR(36), status VARCHAR(20) NOT NULL DEFAULT 'active', version INTEGER NOT NULL DEFAULT 0, created_by VARCHAR(36) NOT NULL REFERENCES app_user(id), created_at VARCHAR(40) NOT NULL, FOREIGN KEY(organization_id,employee_id) REFERENCES employment(organization_id,id), FOREIGN KEY(organization_id,node_id) REFERENCES organization_node(organization_id,id), UNIQUE(organization_id,id), FOREIGN KEY(organization_id,replaces_id) REFERENCES workforce_shift(organization_id,id));
CREATE INDEX workforce_time ON workforce_shift(organization_id,starts_at,ends_at);
CREATE TABLE workforce_policy(organization_id VARCHAR(36) PRIMARY KEY REFERENCES healthcare_organization(id), enforce_availability BOOLEAN NOT NULL DEFAULT FALSE, version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE shift_handoff(id VARCHAR(36) PRIMARY KEY, organization_id VARCHAR(36) NOT NULL REFERENCES healthcare_organization(id), patient_id VARCHAR(36) NOT NULL REFERENCES app_user(id), encounter_id VARCHAR(36) REFERENCES appointment(id), outgoing_id VARCHAR(36) NOT NULL REFERENCES app_user(id), incoming_id VARCHAR(36) NOT NULL REFERENCES app_user(id), details TEXT NOT NULL, status VARCHAR(20) NOT NULL, acknowledged_at VARCHAR(40), created_at VARCHAR(40) NOT NULL, version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE organization_event(seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id VARCHAR(36) NOT NULL UNIQUE, organization_id VARCHAR(36) NOT NULL REFERENCES healthcare_organization(id), actor_id VARCHAR(36) REFERENCES app_user(id), patient_id VARCHAR(36) REFERENCES app_user(id), resource_type VARCHAR(40) NOT NULL, resource_id VARCHAR(100) NOT NULL, action VARCHAR(80) NOT NULL, severity VARCHAR(20) NOT NULL, created_at VARCHAR(40) NOT NULL, previous_value TEXT, new_value TEXT);
CREATE INDEX org_event_cursor ON organization_event(organization_id,seq);
ALTER TABLE clinical_record ADD COLUMN tenant_id VARCHAR(36) REFERENCES healthcare_organization(id);
ALTER TABLE medical_document ADD COLUMN tenant_id VARCHAR(36) REFERENCES healthcare_organization(id);
ALTER TABLE appointment ADD COLUMN tenant_id VARCHAR(36) REFERENCES healthcare_organization(id);
ALTER TABLE care_task ADD COLUMN tenant_id VARCHAR(36) REFERENCES healthcare_organization(id);
ALTER TABLE care_task ADD COLUMN task_type VARCHAR(40) NOT NULL DEFAULT 'care_task';
ALTER TABLE care_task ADD COLUMN location_label VARCHAR(120);
ALTER TABLE care_task ADD COLUMN completed_at VARCHAR(40);
ALTER TABLE care_task ADD COLUMN verified_by VARCHAR(36) REFERENCES app_user(id);
ALTER TABLE care_task ADD COLUMN verified_at VARCHAR(40);
CREATE TABLE task_dependency(task_id VARCHAR(36) NOT NULL REFERENCES care_task(id), depends_on VARCHAR(36) NOT NULL REFERENCES care_task(id), PRIMARY KEY(task_id,depends_on), CHECK(task_id<>depends_on));
CREATE INDEX record_tenant ON clinical_record(tenant_id,patient_id);
CREATE TABLE clinical_order(id VARCHAR(36) PRIMARY KEY, organization_id VARCHAR(36) NOT NULL REFERENCES healthcare_organization(id), record_id VARCHAR(36) NOT NULL UNIQUE REFERENCES clinical_record(id), patient_id VARCHAR(36) NOT NULL REFERENCES app_user(id), encounter_id VARCHAR(36) REFERENCES appointment(id), kind VARCHAR(30) NOT NULL, code VARCHAR(100) NOT NULL, modality VARCHAR(30), instructions TEXT NOT NULL, priority VARCHAR(20) NOT NULL, status VARCHAR(30) NOT NULL, assigned_id VARCHAR(36) NOT NULL REFERENCES app_user(id), requester_id VARCHAR(36) NOT NULL REFERENCES app_user(id), task_id VARCHAR(36) REFERENCES care_task(id), specimen_type VARCHAR(80), specimen_code VARCHAR(40) UNIQUE, collected_by VARCHAR(36) REFERENCES app_user(id), collected_at VARCHAR(40), result_id VARCHAR(36) REFERENCES clinical_record(id), critical BOOLEAN NOT NULL DEFAULT FALSE, study_uid VARCHAR(100), created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, version INTEGER NOT NULL DEFAULT 0);
CREATE INDEX clinical_order_queue ON clinical_order(organization_id,kind,status);
